// Multiple classes in one file for the runnable demo.
package com.bank.pulsar;

import java.util.List;
import java.util.logging.*;

public class PulsarEvalDemo {

    private static final Logger log = Logger.getLogger(PulsarEvalDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Multi-tenancy: one tenant 'nbi', isolated namespaces with their own retention.
        Namespace trading = new Namespace("nbi", "trading", "7y");
        PulsarTopic trades = trading.createTopic("persistent://nbi/trading/trade.events");

        // Publish trade events (durable append to BookKeeper-like log).
        trades.publish("T-1", "RELIANCE buy 100 for SAV2001");
        trades.publish("T-2", "RELIANCE sell 50 for CUR3001");
        trades.publish("T-3", "TCS buy 10 for SAV2001");

        // SHARED subscription = work queue, per-message ack across worker pool.
        log.info("=== SHARED subscription (work queue, per-message ack) ===");
        Subscription settleWorkers = trades.subscribe("settle-workers", Subscription.Type.SHARED);
        settleWorkers.addConsumer("worker-A");
        settleWorkers.addConsumer("worker-B");
        settleWorkers.dispatchAll();          // round-robin to A and B, each acked individually

        // EXCLUSIVE subscription = ordered replayable stream from the SAME topic.
        log.info("=== EXCLUSIVE subscription (ordered replayable stream) ===");
        Subscription audit = trades.subscribe("audit", Subscription.Type.EXCLUSIVE);
        audit.addConsumer("audit-reader");
        audit.dispatchAll();                  // single consumer reads all in order
        log.info("=== Replay audit from start (durable log) ===");
        audit.replayFromStart();

        // Multi-tenancy isolation: a different namespace, different policy.
        Namespace payments = new Namespace("nbi", "payments", "30d");
        payments.createTopic("persistent://nbi/payments/upi.events");
        log.info(() -> "Tenant nbi has isolated namespaces: trading(7y) and payments(30d)");

        // Built-in geo-replication at namespace level.
        trading.geoReplicateTo("dr-pune");
    }
}

