class PulsarTopic {
    private static final Logger log = Logger.getLogger(PulsarTopic.class.getName());
    private final String fqName;                          // persistent://tenant/ns/topic
    final java.util.List<String[]> ledger = new java.util.ArrayList<>(); // BookKeeper-like
    PulsarTopic(String fqName) { this.fqName = fqName; }

    void publish(String key, String payload) {
        ledger.add(new String[]{key, payload});
        log.fine(() -> "append " + fqName + " key=" + key + " -> " + payload);
    }

    Subscription subscribe(String name, Subscription.Type type) {
        log.info(() -> "subscribe " + name + " type=" + type + " on " + fqName);
        return new Subscription(name, type, this);
    }
}

// ─── Would be in core/Subscription.java ───
class Subscription {
    enum Type { EXCLUSIVE, FAILOVER, SHARED, KEY_SHARED }
    private static final Logger log = Logger.getLogger(Subscription.class.getName());
    private final String name;
    private final Type type;
    private final PulsarTopic topic;
    private final java.util.List<String> consumers = new java.util.ArrayList<>();
    Subscription(String name, Type type, PulsarTopic topic) {
            this.name = name;
            this.type = type
            this.topic = topic;
    }

    void addConsumer(String c) { consumers.add(c); }

    void dispatchAll() {
        int i = 0;
        for (String[] msg : topic.ledger) {
            if (type == Type.SHARED) {
                String consumer = consumers.get(i % consumers.size());   // round-robin
                log.info(() -> "SHARED -> " + consumer + " msg=" + msg[0]
                        + "  (ack individually)");
                i++;
            } else { // EXCLUSIVE / FAILOVER: single active consumer, ordered
                String consumer = consumers.get(0);
                log.info(() -> type + " -> " + consumer + " msg=" + msg[0] + "  (in order)");
            }
        }
    }

    void replayFromStart() {                                 // durable log => replay
        for (String[] msg : topic.ledger)
            log.info(() -> "REPLAY " + name + " msg=" + msg[0] + " -> " + msg[1]);
    }
}

