class Namespace {
    private static final Logger log = Logger.getLogger(Namespace.class.getName());
    private final String tenant;
    private final String namespace;
    private final String retention;
    Namespace(String tenant, String namespace, String retention) {
            this.tenant = tenant;
            this.namespace = namespace
            this.retention = retention;
        log.info(() -> "namespace created " + tenant + "/" + namespace
                + " retention=" + retention);
    }

    PulsarTopic createTopic(String fqName) {
        log.fine(() -> "create topic " + fqName + " under " + tenant + "/" + namespace);
        return new PulsarTopic(fqName);
    }

    void geoReplicateTo(String cluster) {                    // built-in geo-replication
        log.info(() -> "geo-replicate " + tenant + "/" + namespace + " -> cluster " + cluster);
    }
}

